@'
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {configureWorker} from './integrations/pi/worker-runtime.mjs';
import {resolveProvider,probePiProviderCapabilities,createProviderRequest} from './integrations/pi/provider.mjs';
process.env.FORGEWRIGHT_ENABLE_PI_GOOGLE_API='1';
process.env.GOOGLE_GENERATIVE_AI_API_KEY='supervisor-synthetic-not-a-real-key';
let networkCalls=0;
globalThis.fetch=async()=>{networkCalls++;throw new Error('SUPERVISOR_NETWORK_BLOCKED');};
const root=mkdtempSync(join(tmpdir(),'fw-supervisor-google-'));
let configResult;
try {configResult=await configureWorker(root,{provider:'google-api',authSource:'google-api-key',model:'gemini-4-argon'});}
catch(e){configResult={error:e.code??e.message};}
finally{rmSync(root,{recursive:true,force:true});}
let streamResult;
try{
 const provider=await resolveProvider({provider:'google-api',model:'gemini-4-argon'});
 const req=createProviderRequest(provider,{signal:AbortSignal.timeout(3000),maxTokens:1,timeoutMs:3000});
 const stream=req.stream({messages:[],tools:[]});
 const outcome=await stream.result();
 streamResult={stopReason:outcome.stopReason,errorMessage:outcome.errorMessage,usage:req.settle()};
}catch(e){streamResult={error:e.code??e.message};}
console.log(JSON.stringify({advertised:probePiProviderCapabilities().routes['google-api'],configResult,streamResult,networkCalls}));

